function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function call(path,options={}){const response=await fetch(origin()+path,{headers:{Accept:'application/json','Content-Type':'application/json'},...options});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
async function run(input){if(input.confirm_python_execution!==true)throw new Error('Python Lab requires an explicit user request and confirm_python_execution=true');const capabilities=await call('/api/python-lab/capabilities');if(!capabilities.available)throw new Error(capabilities.reason||'Python Lab runtime is unavailable');if(capabilities.trusted_local&&input.confirm_trusted_local!==true)throw new Error('trusted_local is not a sandbox and requires confirm_trusted_local=true');const projectId=String(input.project_id||'').trim();if(!projectId)throw new Error('project_id is required');const body={project_id:projectId,profile:input.profile==='runtime'?'runtime':'demo',source:String(input.source||''),as_of_date:input.as_of_date||null,lookback_days:Number(input.lookback_days||120),symbols:Array.isArray(input.symbols)?input.symbols:null,max_rows:Number(input.max_rows||50000),confirm_python_execution:true,confirm_trusted_local:input.confirm_trusted_local===true};const result=await call('/api/python-lab/runs',{method:'POST',body:JSON.stringify(body)});return{...result,runtime_capabilities:capabilities}}
